CREATE OR REPLACE FUNCTION public.track_said(p_kind text, p_range integer, p_stage text, p_level integer, p_moving boolean, p_reading jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare v_band int; v_name text;
begin
  if p_reading is null then
    return 'No ' || lower(p_kind) || ' within ' || p_range || ' tiles.';
  end if;
  v_band := (p_reading->>'band')::int;
  v_name := case when track_stage(v_band) then p_stage else p_kind end;
