  end if;
  if track_round(v_band) is null then
    return 'Tracks: ' || v_name || ', ' || (p_reading->>'way') || ', '
      || track_dist_says(p_reading) || '.';
  end if;
  return 'Tracks: ' || v_name || ', ' || (p_reading->>'way') || ', ' || track_dist_says(p_reading) || '.';
end $function$
